const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const repoPath = '/tmp/autobrain-sync';

// Clone or pull latest
if (!fs.existsSync(repoPath)) {
  execSync(`git clone https://github.com/CannonFodder151/autobrain.git ${repoPath}`);
} else {
  execSync(`cd ${repoPath} && git pull origin main`);
}

// Run sync script
const result = execSync('node scripts/sync-docs-outline.mjs', {
  cwd: repoPath,
  env: {
    ...process.env,
    OUTLINE_API_TOKEN: $json.OUTLINE_API_TOKEN || $env.OUTLINE_API_TOKEN,
    OUTLINE_API_URL: $json.OUTLINE_API_URL || $env.OUTLINE_API_URL || 'https://outline.nathanmartina.com'
  },
  encoding: 'utf8',
  maxBuffer: 10 * 1024 * 1024
});

return [{ json: { success: true, output: result } }];
